<?php $pageTitle='Settings';$subtitle='Business controls, maintenance mode and office policy.';$active='Settings';require __DIR__.'/_layout.php';$pdo=db();$office=$pdo->query('SELECT * FROM office_settings WHERE id=1')->fetch();$st=$pdo->query("SELECT setting_key,value FROM site_settings WHERE setting_key IN ('maintenance_mode','maintenance_title','maintenance_message')")->fetchAll();$settings=[];foreach($st as $r)$settings[$r['setting_key']]=$r['value'];?>
<div class="grid two"><section class="card"><div class="section-head"><h2>Maintenance mode</h2><span class="pill <?=($settings['maintenance_mode']??'0')==='1'?'red':'green'?>"><?=($settings['maintenance_mode']??'0')==='1'?'ACTIVE':'OFF'?></span></div><p style="color:var(--muted);line-height:1.7">Temporarily hide the public storefront while keeping admin, employee and authentication access available.</p><form id="maintenanceForm" class="form-grid"><div class="field full"><label class="check"><input type="checkbox" name="enabled" <?=($settings['maintenance_mode']??'0')==='1'?'checked':''?>> Enable maintenance mode</label></div><div class="field full"><label>Maintenance title</label><input class="input" name="title" value="<?=ae($settings['maintenance_title']??'We are upgrading Swarnim Groups')?>"></div><div class="field full"><label>Message</label><textarea class="textarea" name="message" rows="5"><?=ae($settings['maintenance_message']??'Our website is temporarily unavailable while we improve your shopping experience.')?></textarea></div><div class="actions field full"><button class="btn primary" type="submit">Save Maintenance Settings</button></div></form></section><section class="card"><h2>Attendance policy</h2><p style="color:var(--muted);line-height:1.7">The attendance geofence is measured from the office coordinates using the Haversine distance.</p><div class="pill gold">Current radius: <?=number_format((int)$office['radius_meters'])?> m</div><div class="actions" style="margin-top:15px"><a class="btn" href="attendance.php">Attendance</a><a class="btn" href="import.php">Product Import</a><a class="btn" href="broadcast.php">User Messaging</a></div></section></div>
<script>document.querySelector('#maintenanceForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);fd.append('action','save-maintenance');const r=await fetch('api.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':CSRF},credentials:'same-origin'});const j=await r.json();toast(j.message,j.ok);if(j.ok)setTimeout(()=>location.reload(),500)});</script><?php require __DIR__.'/_foot.php'; ?>